/**
 * Mooral Business Suite
 * Official brand logo - base64 data URI
 *
 * This is the SAME source image as src/assets/mooral-logo.png,
 * pre-encoded as a data URI. React UI components should import the
 * PNG directly (`import mooralLogo from "@/assets/mooral-logo.png"`)
 * so Vite serves it as a normal cached asset - this data-URI export
 * exists only for the PDF rendering pipeline (Invoice, Certificates,
 * Reports, Credentials), which needs an embeddable data: URI, not a
 * dev-server-relative asset path, since Electron's off-screen
 * printToPDF window loads a standalone temp HTML file that can't
 * resolve app-relative asset URLs. This is exactly the same format
 * `window.mooral.settings.getLogoPreview()` already returns for a
 * tenant-uploaded company logo, so it can be used as a drop-in
 * fallback wherever that call currently returns null (see each PDF
 * builder's usage for the exact fallback condition).
 *
 * Source: uploaded by the user as the official Mooral Business
 * Suite logo, used unmodified (no cropping/resizing) - it is
 * intentionally NOT re-encoded or trimmed here, so this string is
 * always byte-identical to src/assets/mooral-logo.png.
 */

export const MOORAL_LOGO_DATA_URL = "data:image/png;base64,";
